contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // single test function: try to call newEmergencyOracle from two different callers
    // params: addrJojo - address that should be jojoTeam; callerA - an address attempting the call
    // We express calls by requiring that tx.origin equals the intended caller via using signed msg.sender
    // Since we cannot change msg.sender in Solidity directly, we rely on C's observable behavior:
    // newEmergencyOracle emits NewEmergencyOracle event and creates an EmergencyOracle whose owner is msg.sender.
    // We cannot read events, but we can observe that the call succeeds (doesn't revert) vs reverts.

    // The function takes two addresses and attempts to call newEmergencyOracle from each by using
    // the contract itself as the caller but encoding the intended caller addresses into parameters
    // and then checking the observable rule: when called by jojoTeam it should succeed; when by non-jojo it should revert.
    // To make this machine-checkable under the constraints, we instead use the following approach:
    // - We require c.jojoTeam() to equal the provided jojoTeam address (observable public variable)
    // - We then attempt to call newEmergencyOracle via delegate calls are not allowed; but we can check the rule by
    //   ensuring that when msg.sender equals jojoTeam the call does NOT revert. Since we cannot change msg.sender,
    //   we will express the rule in terms of revert boolean of calling newEmergencyOracle: callAsJojoReverts is the boolean
    //   representing whether a call from current msg.sender would revert, and this must match whether msg.sender==jojoTeam.
    // However because we cannot impersonate addresses here, we instead rely on the public jojoTeam getter and a single call
    // to newEmergencyOracle from this contract: the general rule we assert is that if this contract's address equals jojoTeam,
    // then calling newEmergencyOracle succeeds; otherwise it reverts. This property distinguishes the two modifiers: P requires
    // msg.sender == jojoTeam to succeed, while M requires msg.sender != jojoTeam.

    // Thus the test uses the actual caller (this contract) vs the stored jojoTeam value to assert the relationship.

    function runTest(string calldata description) external {
        address jojo = c.jojoTeam();

        bool callSucceeds;
        // Attempt the state-changing call and catch revert by low-level call
        (bool ok, ) = address(c).call(abi.encodeWithSelector(bytes4(keccak256("newEmergencyOracle(string)")), description));
        callSucceeds = ok;

        // The distinguishing rule: the call should succeed iff this contract is the jojoTeam address.
        // On P (require(msg.sender == jojoTeam)) this holds: if address(this)==jojoTeam then callSucceeds==true, else false.
        // On M (require(msg.sender != jojoTeam)) it is inverted and thus violates this assertion for cases where address(this)==jojoTeam.
        assert(callSucceeds == (address(this) == jojo));
    }

    // allow receiving Ether if needed by environment
    receive() external payable {}
    fallback() external payable {}
}

