pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IEmergencyOracle {
    function turnOnOracle() external;
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;
    address jojo = address(0xABCD);

    function setUp() public { c = new C(); }

    // General idea: fuzz a caller address 'creator' and a description; make that caller be the jojoTeam
    // in the contract, then have the same caller call newEmergencyOracle(description). The freshly deployed
    // EmergencyOracle should accept owner-only calls from the creator (because reference sets owner=msg.sender)
    // while the mutant (which passes jojoTeam into the EmergencyOracle constructor) will set the owner to
    // jojoTeam, and if creator != jojoTeam the owner-only call by creator will revert. We detect this by
    // calling turnOnOracle() on the created oracle address (emitted address is returned by getting the
    // transaction's logs is disallowed, so instead we observe behavior by creating the oracle and then
    // attempting to call turnOnOracle() on the address that was just created — to obtain that address we
    // exploit that new EmergencyOracle is returned via the event NewEmergencyOracle; however events are not
    // readable here, so instead we read the return by using the fact that the new EmergencyOracle is deployed
    // at a deterministic address given the creating address and nonce. To avoid complex deterministic address
    // computation, we rely on the following practical approach: we make the creator create the oracle and then
    // immediately call the newly created contract by iterating nonces until we find a contract whose owner()
    // equals creator or not. This keeps the test universal and fuzzed. (Note: iteration bound kept small.)

    function testFuzz_property(address creator, bytes calldata description) public {
        vm.assume(creator != address(0)); // keep admissible domain wide but exclude zero which can't be a useful EOA
        // Set c.jojoTeam to our chosen jojo and then later change to creator to test both roles
        // first set jojoTeam to some known address (jojo) via direct storage is disallowed; instead we must leverage
        // that C exposes jojoTeam as public and a modifier onlyJojoTeam; but there is no setter — the only way is
        // to set the jojoTeam pre-deployment; given constraints, we'll use low-level trick: deploy a new C instance
        // where we can set jojoTeam by calling from jojo via vm.prank and using storage write is disallowed. To comply
        // with the requirement to use new C() in setUp(), we will instead change approach: we will set jojoTeam by
        // calling via high-level means is impossible; BUT the problem statement allowed setting public variable jojoTeam
        // externally? The provided contract C has jojoTeam public but no setter; however the test can still set the storage
        // slot using vm.store is forbidden. To satisfy constraints, we'll instead make creator equal to jojo by
