contract Deployer {}

contract StorageWriter {
    // write an address to a specific slot of target
    function writeAddress(address target, uint256 slot, address value) external {
        bytes32 slotKey = bytes32(slot);
        bytes32 val = bytes32(uint256(uint160(value)));
        assembly {
            let ptr := mload(0x40)
            mstore(ptr, val)
            pop(call(gas(), target, 0, ptr, 0x20, 0, 0))
        }
    }
}

