// Helper contract to write to storage slot 0 of the target via delegatecall.
contract SetSlotHelper {
    // This function will perform a delegatecall into target with calldata that executes code
    // in this contract context to set storage slot 0 to the provided address. We implement
    // the storage write here and then delegatecall will run this code in the context of the target,
    // modifying its storage.

    // The function that does the write. We will delegatecall this contract's selector on the target.
    function writeSlot0(address newAddr) external {
        assembly {
            // store newAddr into slot 0
            sstore(0, newAddr)
        }
    }

    // Trigger delegatecall on target to run writeSlot0 there
    function callSetSlot(address target, address newAddr) public {
        // selector of writeSlot0(address)
        bytes4 sel = bytes4(keccak256("writeSlot0(address)"));
        (bool success, ) = target.delegatecall(abi.encodeWithSelector(sel, newAddr));
        require(success, "delegatecall failed");
    }
}

